// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceTokenStatsHost {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceTokenStatsHost = UniffiVTableCallbackInterfaceTokenStatsHost(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeTokenStatsHost.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface TokenStatsHost: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeTokenStatsHost.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface TokenStatsHost: handle missing in uniffiClone")
            }
        },
        secondsFromGmt: { (
            uniffiHandle: UInt64,
            epochSeconds: Int64,
            uniffiOutReturn: UnsafeMutablePointer<Int32>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> Int32 in
                guard let uniffiObj = try? FfiConverterTypeTokenStatsHost.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.secondsFromGmt(
                     epochSeconds: try FfiConverterInt64.lift(epochSeconds)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterInt32.lower($0) }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        loadWorktreeOrigins: { (
            uniffiHandle: UInt64,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> [FfiOrigin] in
                guard let uniffiObj = try? FfiConverterTypeTokenStatsHost.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.loadWorktreeOrigins(
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterSequenceTypeFfiOrigin.lower($0) }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        recordLiveWorktrees: { (
            uniffiHandle: UInt64,
            folds: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterTypeTokenStatsHost.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.recordLiveWorktrees(
                     folds: try FfiConverterSequenceTypeFfiLiveFold.lift(folds)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceTokenStatsHost> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceTokenStatsHost>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitTokenStatsHost() {
    uniffi_tally_ffi_fn_init_callback_vtable_tokenstatshost(UniffiCallbackInterfaceTokenStatsHost.vtablePtr)
}

