 * them with Swift's own answers (eq, has_prefix, count, split, trim, munged).
 */
public func tokenStatsSwiftStrProbe(op: String, a: String, b: String) -> String  {
    return try!  FfiConverterString.lift(try! rustCall() {
        uniffiCallStatus in
    uniffi_tally_ffi_fn_func_token_stats_swift_str_probe(
        FfiConverterString.lower(op),
        FfiConverterString.lower(a),
        FfiConverterString.lower(b),uniffiCallStatus
    )
})
}

